    if (rVclWindowEvent.GetId() == VclEventId::EditModify)
    {
        css::uno::Any aNewValue = getCurrentValue();
        NotifyAccessibleEvent(AccessibleEventId::VALUE_CHANGED, css::uno::Any(), aNewValue);
    }
}
